public static container getHierarchyRolesForPricing()
{
    container hierarchyRoles = RetailCategoryPriceRule::allowedCategoryHierarchyRoles();

    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::Procurement);
    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::Sales);
    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::Commodity);
    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::Financials);
    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::PackingMaterials_W);
    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::CommonDataService);
    hierarchyRoles = conIns(hierarchyRoles, 1, EcoResCategoryNamedHierarchyRole::CostManagement);

    return hierarchyRoles;
}
